ALTER TABLE "flow_process" ADD COLUMN "form_type" smallint NULL DEFAULT NULL;
COMMENT ON COLUMN "flow_process"."form_type" IS '表单类型';

ALTER TABLE "flow_process" ADD COLUMN "form_id" integer NULL DEFAULT NULL;
